head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[multiselect > M > getAllValue]<br/>모든 아이템의 Value 값을 separator 속성값으로 구분한 문자열로 반환합니다.",
    "validation" : [
        "아이템의 선택과 무관하게 전체 아이템의 Value 값을 separator 속성값으로 구분한 문자열로 반환합니다.",
        "전체 아이템의 Value 값을 separator 속성값으로 구분한 문자열로 반환합니다.",
        "아이템이 없으면 빈 문자열('')을 반환합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (BindItemSet: gdl_multiselect 와 바인딩, separator 속성 적용)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    // separator 속성값 (con_separator 선택값)
    let cSeparator = con_separator.getText();

    let properties = {};
    if (cSeparator !== "") {
        properties.separator = cSeparator;
    }
    let cList = $c.gcm.createCList(properties);

    // 현재 적용된 separator 정보 라벨 표시
    $c.gcm.createLabel('label="target1 : separator=[' + (cSeparator === "" ? "미설정(기본 공백)" : cSeparator) + ']"', '', 'label1');

    // comp 생성 함수 호출
    $c.gcm.createBasicMultiSelect(cList);
}



// getAllValue 호출 (선택과 무관하게 전체 아이템 Value 반환)
scwin.btn_getAllValue_onclick = function (e) {
    let rtn = target1.getAllValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getAllValue() : [" + rtn + "]");
};



// getValue 호출 (비교용 - 선택된 아이템의 Value 만 반환)
scwin.btn_getValue_onclick = function (e) {
    let rtn = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getValue() : [" + rtn + "]");
};



// 인덱스 1 아이템만 선택 (선택과 무관 검증용)
scwin.btn_selectOne_onclick = function (e) {
    target1.setValue("");
    target1.setSelectedIndexNM(1, true);
    target1.setInstanceValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 인덱스 1 아이템만 선택 완료");
};



// 인덱스 0, 2 아이템 선택 (다중 선택 케이스)
scwin.btn_selectTwo_onclick = function (e) {
    target1.setValue("");
    target1.setSelectedIndexNM(0, true);
    target1.setSelectedIndexNM(2, true);
    target1.setInstanceValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 인덱스 0, 2 아이템 선택 완료");
};



// 전체 아이템 모두 해제
scwin.btn_clearSelection_onclick = function (e) {
    target1.setValue("");
    target1.setInstanceValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 전체 선택 해제 완료");
};



// 모든 아이템 제거 (아이템 없을 때 빈 문자열 반환 검증용)
// BindItemSet 모드에서 deleteItem(i, false)이 정상 동작하지 않아 dataList 를 직접 비움
scwin.btn_deleteAllItems_onclick = function (e) {
    gdl_multiselect.removeAll();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 전체 아이템 제거 완료 (현재 itemCount=" + target1.getItemCount() + ")");
};
